cd /testbed && PYTHONPATH=src python - <<'PY'
from flask import Blueprint, Flask

app = Flask(__name__)
try:
    app.add_url_rule("/x", "a.b", lambda: "ok")
except ValueError as e:
    endpoint_error = e
else:
    raise SystemExit("endpoint name 'a.b' was accepted; baseline 1.0 check missing")

if not isinstance(endpoint_error, ValueError):
    raise SystemExit(f"unexpected endpoint error type: {type(endpoint_error)!r}")

for bad in ("a.b", "a.b.c", ".leading", "trailing."):
    try:
        Blueprint(bad, __name__)
    except ValueError:
        continue
    except Exception as e:
        raise SystemExit(
            f"Blueprint({bad!r}) raised {type(e).__name__}, expected ValueError "
            f"like the endpoint check: {e}"
        )
    raise SystemExit(f"Blueprint({bad!r}) was accepted; dotted names must fail")

print("B1 ok")
PY
